/**
 * CSV catalog parser (see README.md contract).
 *
 * Public API: parseCatalog(csvText) -> [{ id: string, name: string, price: number }]
 *
 * - Header must be `id,name,price` (order sensitive, case/whitespace tolerant).
 * - RFC 4180 style fields: double quotes may wrap a field, quoted fields may
 *   contain commas and line breaks, and `""` inside a quoted field is an
 *   escaped literal quote.
 * - LF, CRLF and trailing-newline inputs are all accepted.
 * - Empty input yields an empty catalog; blank (whitespace-only) lines are ignored,
 *   while a line that does carry delimiters is still validated.
 * - Rows with the wrong number of columns, empty ids, and negative or
 *   non-finite / non-numeric prices are rejected with an Error.
 *
 * No runtime dependencies.
 */

const HEADER = ['id', 'name', 'price'];
const PRICE_RE = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;

/**
 * Split raw CSV text into rows of cells, keeping track of each row's line number.
 * Throws on an unterminated quoted field.
 */
function splitRows(text) {
  const rows = [];
  let cells = [];
  let field = '';
  let inQuotes = false;
  let fieldQuoted = false;
  let rowQuoted = false;
  let line = 1;
  let i = 0;

  const endField = () => {
    cells.push(field);
    field = '';
    fieldQuoted = false;
  };

  const endRow = () => {
    endField();
    // A line holding nothing but whitespace carries no data (no delimiters, no
    // quoting): skip it as a blank line.
    const blank = cells.length === 1 && cells[0].trim() === '' && !rowQuoted;
    if (!blank) rows.push({ cells, line });
    cells = [];
    rowQuoted = false;
  };

  while (i < text.length) {
    const ch = text[i];

    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          field += '"'; // escaped quote
          i += 2;
          continue;
        }
        inQuotes = false; // closing quote
        i += 1;
        continue;
      }
      if (ch === '\n') line += 1; // line break inside a quoted field
      field += ch;
      i += 1;
      continue;
    }

    if (ch === '"') {
      if (field === '' && !fieldQuoted) {
        inQuotes = true;
        fieldQuoted = true;
        rowQuoted = true;
      } else {
        field += '"'; // stray quote inside an unquoted field: keep it literal
      }
      i += 1;
      continue;
    }

    if (ch === ',') {
      endField();
      i += 1;
      continue;
    }

    if (ch === '\r' || ch === '\n') {
      if (ch === '\r' && text[i + 1] === '\n') i += 1; // consume CRLF as one break
      endRow();
      line += 1;
      i += 1;
      continue;
    }

    field += ch;
    i += 1;
  }

  if (inQuotes) {
    throw new Error(`parseCatalog: unterminated quoted field on line ${line}`);
  }
  if (field !== '' || cells.length > 0 || rowQuoted) endRow();

  return rows;
}

function parsePrice(raw, line) {
  const value = raw.trim();
  if (!PRICE_RE.test(value)) {
    throw new Error(`parseCatalog: invalid price ${JSON.stringify(raw)} on line ${line}`);
  }
  const price = Number(value);
  if (!Number.isFinite(price)) {
    throw new Error(`parseCatalog: non-finite price ${JSON.stringify(raw)} on line ${line}`);
  }
  if (price < 0) {
    throw new Error(`parseCatalog: negative price ${JSON.stringify(raw)} on line ${line}`);
  }
  return price === 0 ? 0 : price; // normalise -0 to 0
}

function toItem(row) {
  const { cells, line } = row;
  if (cells.length !== HEADER.length) {
    throw new Error(
      `parseCatalog: malformed row on line ${line}: expected ${HEADER.length} columns, found ${cells.length}`,
    );
  }
  const [id, name, priceText] = cells;
  if (id.trim() === '') {
    throw new Error(`parseCatalog: malformed row on line ${line}: empty id`);
  }
  return { id, name, price: parsePrice(priceText, line) };
}

/**
 * Parse catalog CSV text into an array of items.
 *
 * @param {string|null|undefined} csvText
 * @returns {Array<{id: string, name: string, price: number}>}
 */
export function parseCatalog(csvText) {
  // Empty input -> empty catalog.
  if (csvText === null || csvText === undefined) return [];
  if (typeof csvText !== 'string') {
    throw new TypeError(`parseCatalog: csvText must be a string, got ${typeof csvText}`);
  }

  const text = csvText.charCodeAt(0) === 0xfeff ? csvText.slice(1) : csvText; // strip BOM
  if (text.trim() === '') return [];

  const rows = splitRows(text);
  if (rows.length === 0) return [];

  const [header, ...body] = rows;
  const headerCells = header.cells.map((cell) => cell.trim().toLowerCase());
  if (
    headerCells.length !== HEADER.length ||
    headerCells.some((cell, index) => cell !== HEADER[index])
  ) {
    throw new Error(
      `parseCatalog: malformed header on line ${header.line}: expected "${HEADER.join(',')}"`,
    );
  }

  return body.map(toItem);
}

/**
 * src/search.mjs — independent catalog search/filter module.
 *
 * Public contract (README.md):
 *   searchCatalog(items, { query = '', minPrice = 0, maxPrice = Infinity } = {})
 *     - case-insensitive substring search on `name`
 *     - inclusive price bounds
 *     - preserves input order
 *     - never mutates the input array or the item objects
 *     - rejects invalid bounds
 *
 * This module is dependency-free: no imports, no runtime deps, no network
 * services, and it deliberately depends on nothing else in this repo (the
 * parallel parser workstream owns its own module file).
 */

/** Format a value for an error message without ever throwing on weird input. */
function describe(value) {
  if (typeof value === 'number') return value;
  if (typeof value === 'string') return JSON.stringify(value);
  if (value === null) return 'null';
  if (typeof value === 'object') {
    const ctor = value.constructor && value.constructor.name;
    return `an object (${typeof ctor === 'string' && ctor !== 'Object' ? ctor : 'Object'})`;
  }
  return `${typeof value} ${String(value)}`;
}

/**
 * Validate a single numeric bound.
 *
 * @param {string} name  option name, used in error messages
 * @param {unknown} value
 * @param {boolean} allowPositiveInfinity  only `maxPrice` may be Infinity
 */
function assertBound(name, value, { allowPositiveInfinity }) {
  if (typeof value !== 'number' || Number.isNaN(value)) {
    throw new TypeError(
      `searchCatalog: ${name} must be a number, received ${describe(value)}`,
    );
  }
  if (value < 0) {
    throw new RangeError(
      `searchCatalog: ${name} must not be negative, received ${value}`,
    );
  }
  if (!Number.isFinite(value) && !allowPositiveInfinity) {
    throw new RangeError(
      `searchCatalog: ${name} must be a finite number, received ${value}`,
    );
  }
}

/** Validate every option that influences matching. Returns the normalized filter. */
function normalizeOptions(query, minPrice, maxPrice) {
  if (typeof query !== 'string') {
    throw new TypeError(
      `searchCatalog: query must be a string, received ${describe(query)}`,
    );
  }
  assertBound('minPrice', minPrice, { allowPositiveInfinity: false });
  assertBound('maxPrice', maxPrice, { allowPositiveInfinity: true });
  if (minPrice > maxPrice) {
    throw new RangeError(
      `searchCatalog: invalid price bounds, minPrice (${minPrice}) exceeds maxPrice (${maxPrice})`,
    );
  }
  return { needle: query.toLowerCase(), minPrice, maxPrice };
}

/**
 * Filter a catalog by a case-insensitive substring of `name` plus an
 * inclusive price window, preserving input order.
 *
 * @template {object} T
 * @param {readonly T[]} items           catalog rows (never mutated)
 * @param {object} [options]
 * @param {string} [options.query='']    substring searched in `name`, case-insensitive
 * @param {number} [options.minPrice=0]  inclusive lower price bound
 * @param {number} [options.maxPrice=Infinity] inclusive upper price bound
 * @returns {T[]} new array holding references to the matching input items
 */
export function searchCatalog(items, { query = '', minPrice = 0, maxPrice = Infinity } = {}) {
  if (!Array.isArray(items)) {
    throw new TypeError(
      `searchCatalog: items must be an array, received ${describe(items)}`,
    );
  }

  const { needle, minPrice: low, maxPrice: high } = normalizeOptions(query, minPrice, maxPrice);
  const matches = [];

  for (const item of items) {
    if (item === null || typeof item !== 'object') continue;

    // Read each field at most once (getter-friendly) and only as needed.
    const name = item.name;
    if (typeof name !== 'string') continue;
    if (needle !== '' && !name.toLowerCase().includes(needle)) continue;

    const price = item.price;
    if (typeof price !== 'number' || Number.isNaN(price)) continue;
    if (price < low || price > high) continue;

    matches.push(item);
  }

  return matches;
}

export default searchCatalog;

import { test } from 'node:test';
import assert from 'node:assert/strict';

import { parseCatalog } from '../src/csv.mjs';

const HEADER = 'id,name,price\n';

// ---------------------------------------------------------------- happy paths

test('parses a simple catalog and returns {id, name, price} objects', () => {
  const items = parseCatalog(`${HEADER}1,Widget,9.99\n2,Gadget,19.5\n`);
  assert.deepEqual(items, [
    { id: '1', name: 'Widget', price: 9.99 },
    { id: '2', name: 'Gadget', price: 19.5 },
  ]);
});

test('return shape: array of plain objects with exactly id/name/price keys and types', () => {
  const items = parseCatalog('id,name,price\na-1,Thing,0');
  assert.ok(Array.isArray(items));
  assert.equal(items.length, 1);
  assert.deepEqual(Object.keys(items[0]), ['id', 'name', 'price']);
  assert.equal(typeof items[0].id, 'string');
  assert.equal(typeof items[0].name, 'string');
  assert.equal(typeof items[0].price, 'number');
  assert.equal(Number.isFinite(items[0].price), true);
});

test('last row without a trailing newline is parsed', () => {
  assert.deepEqual(parseCatalog('id,name,price\n7,Bolt,0.25'), [
    { id: '7', name: 'Bolt', price: 0.25 },
  ]);
});

test('handles quoted commas inside fields', () => {
  const items = parseCatalog('id,name,price\n1,"Widget, large",9.99\n');
  assert.deepEqual(items, [{ id: '1', name: 'Widget, large', price: 9.99 }]);
});

test('handles several quoted fields on the same row', () => {
  const items = parseCatalog('id,name,price\n"A-1","Desk, oak","1200.00"\n');
  assert.deepEqual(items, [{ id: 'A-1', name: 'Desk, oak', price: 1200 }]);
});

test('handles escaped double quotes inside quoted fields', () => {
  const items = parseCatalog('id,name,price\n1,"The ""Big"" One",5\n');
  assert.deepEqual(items, [{ id: '1', name: 'The "Big" One', price: 5 }]);
});

test('handles a field that is only an escaped quote', () => {
  const items = parseCatalog('id,name,price\n1,"""",5\n');
  assert.deepEqual(items, [{ id: '1', name: '"', price: 5 }]);
});

test('quoted fields may contain newlines (LF)', () => {
  const items = parseCatalog('id,name,price\n1,"Line one\nLine two",3\n');
  assert.deepEqual(items, [{ id: '1', name: 'Line one\nLine two', price: 3 }]);
});

test('handles CRLF line endings, including CRLF inside a quoted field', () => {
  const items = parseCatalog('id,name,price\r\n1,"Widget, big\r\nsecond line",9.99\r\n2,Gizmo,1\r\n');
  assert.deepEqual(items, [
    { id: '1', name: 'Widget, big\r\nsecond line', price: 9.99 },
    { id: '2', name: 'Gizmo', price: 1 },
  ]);
});

test('lone CR line endings also terminate rows', () => {
  const items = parseCatalog('id,name,price\r1,A,1\r2,B,2\r');
  assert.deepEqual(items, [
    { id: '1', name: 'A', price: 1 },
    { id: '2', name: 'B', price: 2 },
  ]);
});

test('empty string input returns an empty catalog', () => {
  assert.deepEqual(parseCatalog(''), []);
});

test('whitespace-only and newline-only input returns an empty catalog', () => {
  assert.deepEqual(parseCatalog('   '), []);
  assert.deepEqual(parseCatalog('\n'), []);
  assert.deepEqual(parseCatalog('\r\n\r\n'), []);
  assert.deepEqual(parseCatalog('\t \n '), []);
});

test('nullish input is treated as empty input', () => {
  assert.deepEqual(parseCatalog(null), []);
  assert.deepEqual(parseCatalog(undefined), []);
  assert.deepEqual(parseCatalog(), []);
});

test('header-only input (with and without trailing newline) returns an empty catalog', () => {
  assert.deepEqual(parseCatalog('id,name,price'), []);
  assert.deepEqual(parseCatalog('id,name,price\n'), []);
  assert.deepEqual(parseCatalog('id,name,price\r\n'), []);
});

test('blank lines between rows are ignored', () => {
  const items = parseCatalog('id,name,price\n1,A,1\n\n   \n2,B,2\n\n');
  assert.deepEqual(items, [
    { id: '1', name: 'A', price: 1 },
    { id: '2', name: 'B', price: 2 },
  ]);
});

test('a line that only holds delimiters is still a malformed row, not a blank line', () => {
  assert.throws(() => parseCatalog(`${HEADER}1,A,1\n,,\n`), /malformed row on line 3|empty id/i);
});

test('header matching is case and whitespace tolerant', () => {
  const items = parseCatalog(' ID , Name , PRICE \n1,A,1');
  assert.deepEqual(items, [{ id: '1', name: 'A', price: 1 }]);
});

test('a leading UTF-8 BOM is tolerated', () => {
  const items = parseCatalog('\uFEFFid,name,price\n1,A,1');
  assert.deepEqual(items, [{ id: '1', name: 'A', price: 1 }]);
});

test('price formats: integers, decimals, leading dot, zero, exponents, leading +', () => {
  const items = parseCatalog(
    'id,name,price\n1,a,10\n2,b,0.5\n3,c,.25\n4,d,0\n5,e,1e2\n6,f,+3.75\n7,g,1.5E-2\n8,h, 8 \n',
  );
  assert.deepEqual(
    items.map((item) => item.price),
    [10, 0.5, 0.25, 0, 100, 3.75, 0.015, 8],
  );
});

test('zero price is allowed and never reported as -0', () => {
  const items = parseCatalog('id,name,price\n1,Free,0\n2,AlsoFree,-0');
  assert.equal(items[0].price, 0);
  assert.equal(Object.is(items[1].price, 0), true); // not Object.is(-0)
});

test('field values other than the header are preserved verbatim', () => {
  const items = parseCatalog('id,name,price\n  x1 , Spaced  Name ,1\n');
  assert.deepEqual(items, [{ id: '  x1 ', name: ' Spaced  Name ', price: 1 }]);
});

test('an empty name is allowed', () => {
  assert.deepEqual(parseCatalog('id,name,price\n1,,5'), [{ id: '1', name: '', price: 5 }]);
  assert.deepEqual(parseCatalog('id,name,price\n1,"",5'), [{ id: '1', name: '', price: 5 }]);
});

test('each call returns fresh arrays and objects (no shared state)', () => {
  const csv = `${HEADER}1,A,1\n`;
  const first = parseCatalog(csv);
  const second = parseCatalog(csv);
  assert.notEqual(first, second);
  assert.notEqual(first[0], second[0]);
  assert.deepEqual(first, second);
});

test('large catalog keeps order and count', () => {
  const lines = ['id,name,price'];
  for (let n = 1; n <= 500; n += 1) lines.push(`${n},Item ${n},${n / 2}`);
  const items = parseCatalog(`${lines.join('\n')}\n`);
  assert.equal(items.length, 500);
  assert.equal(items[0].id, '1');
  assert.equal(items[499].name, 'Item 500');
  assert.equal(items[499].price, 250);
});

// ------------------------------------------------------------- rejections

test('rejects a non-string csvText with a TypeError', () => {
  assert.throws(() => parseCatalog(42), TypeError);
  assert.throws(() => parseCatalog(['id,name,price']), TypeError);
  assert.throws(() => parseCatalog({}), TypeError);
  assert.throws(() => parseCatalog(true), TypeError);
});

test('rejects a missing or malformed header', () => {
  assert.throws(() => parseCatalog('1,Widget,9.99\n'), /header/i);
  assert.throws(() => parseCatalog('id,name\n1,Widget\n'), /header/i);
  assert.throws(() => parseCatalog('name,id,price\nWidget,1,9.99\n'), /header/i);
  assert.throws(() => parseCatalog('id,name,price,extra\n1,Widget,9.99,x\n'), /header/i);
  assert.throws(() => parseCatalog('id,price\n1,2\n'), /header/i);
});

test('rejects rows with too few columns', () => {
  assert.throws(() => parseCatalog(`${HEADER}1,Widget\n`), /malformed row on line 2/i);
  assert.throws(() => parseCatalog(`${HEADER}1\n`), /malformed row on line 2/i);
});

test('rejects rows with too many columns', () => {
  assert.throws(() => parseCatalog(`${HEADER}1,Widget,9.99,extra\n`), /malformed row on line 2/i);
});

test('an unquoted comma inside a price is treated as a malformed row', () => {
  assert.throws(() => parseCatalog(`${HEADER}1,Widget,1,200.00\n`), /malformed row on line 2/i);
});

test('reports the offending line number for later rows', () => {
  assert.throws(() => parseCatalog(`${HEADER}1,A,1\n2,B,2\n3,C\n`), /line 4/);
  assert.throws(() => parseCatalog('id,name,price\r\n1,A,1\r\n2,B,bad\r\n'), /line 3/);
});

test('rejects negative prices', () => {
  assert.throws(() => parseCatalog(`${HEADER}1,Widget,-9.99\n`), /negative price/i);
  assert.throws(() => parseCatalog(`${HEADER}1,Widget,-1e3\n`), /negative price/i);
});

test('rejects non-finite prices', () => {
  for (const bad of ['NaN', 'nan', 'Infinity', '-Infinity', 'infinity', '1e400', '1.0e+999']) {
    assert.throws(() => parseCatalog(`id,name,price\n1,Widget,${bad}\n`), /price/i, bad);
  }
});

test('rejects non-numeric or empty prices', () => {
  for (const bad of ['', '   ', 'abc', '9.99.9', 'D9.99', '0x10', '1e', '.', '--1']) {
    assert.throws(() => parseCatalog(`id,name,price\n1,Widget,${bad}\n`), /invalid price/i, bad);
  }
});

test('rejects a quoted price containing a comma', () => {
  assert.throws(() => parseCatalog('id,name,price\n1,Widget,"1,200.00"\n'), /invalid price/i);
});

test('rejects rows with an empty id', () => {
  assert.throws(() => parseCatalog(`${HEADER},Widget,9.99\n`), /empty id/i);
  assert.throws(() => parseCatalog(`${HEADER}"",Widget,9.99\n`), /empty id/i);
  assert.throws(() => parseCatalog(`${HEADER} ,Widget,9.99\n`), /empty id/i);
});

test('rejects an unterminated quoted field', () => {
  assert.throws(() => parseCatalog('id,name,price\n1,"Widget,9.99\n'), /unterminated quoted field/i);
  assert.throws(() => parseCatalog('id,name,price\n1,"Widget'), /unterminated quoted field/i);
});

test('a parse failure rejects the whole call rather than yielding partial data', () => {
  assert.throws(() => parseCatalog(`${HEADER}1,A,1\n2,B,2\n3,C,oops\n`), /price/i);
});

test('malformed header does not throw for empty input', () => {
  assert.deepEqual(parseCatalog(''), []);
});

/**
 * tests/search.test.mjs — unit tests for src/search.mjs.
 *
 * Uses only Node's built-in test runner (`node --test`), which discovers this
 * file via the `*.test.mjs` pattern. No third-party deps, no network, and no
 * dependency on the parallel CSV workstream (src/csv.mjs / tests/csv.test.mjs).
 */

import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

import { searchCatalog } from '../src/search.mjs';

/* ------------------------------------------------------------------ helpers */

/** Fixture factory: a fresh array of fresh objects for every test. */
function fixtures() {
  return [
    { id: '1', name: 'Green Tea', price: 3.5 },
    { id: '2', name: 'green coffee', price: 12 },
    { id: '3', name: 'Earl GREY', price: 8.25 },
    { id: '4', name: 'Matcha Powder', price: 0 },
    { id: '5', name: 'Olive Oil', price: 100 },
  ];
}

const names = (rows) => rows.map((r) => r.name);
const clone = (rows) => rows.map((r) => ({ ...r }));

/** Snapshot every observable mutation channel on the input. */
function mutationGuard(rows) {
  const snapshot = JSON.stringify(rows);
  return {
    assertClean(label = 'input') {
      assert.equal(JSON.stringify(rows), snapshot, `${label}: array contents were mutated`);
      assert.ok(Array.isArray(rows), `${label}: array was replaced`);
    },
  };
}

/* --------------------------------------------------------------- signature */

test('searchCatalog is exported as a function taking (items, options?)', () => {
  assert.equal(typeof searchCatalog, 'function');
  // Function.length stops at the first parameter with a default, so the
  // defaulted options object is not counted: arity is 1 for items only.
  assert.equal(searchCatalog.length, 1);
});

test('second argument is optional (omitted entirely)', () => {
  const items = fixtures();
  assert.deepEqual(names(searchCatalog(items)), names(items));
});

test('options may be an empty object, applying all documented defaults', () => {
  const items = fixtures();
  assert.deepEqual(names(searchCatalog(items, {})), names(items));
});

test('defaults are query="", minPrice=0, maxPrice=Infinity (per README)', () => {
  const items = fixtures();

  // minPrice defaults to 0: a 0-priced item survives, a negative-priced one does not.
  const withNegatives = [
    { id: 'n', name: 'Refund', price: -1 },
    { id: 'z', name: 'Sample', price: 0 },
  ];
  assert.deepEqual(names(searchCatalog(withNegatives)), ['Sample']);
  assert.deepEqual(names(searchCatalog(withNegatives, { minPrice: 0 })), ['Sample']);

  // maxPrice defaults to Infinity: huge prices survive with only minPrice given.
  const expensive = [{ id: 'e', name: 'Telescope', price: Number.MAX_VALUE }];
  assert.deepEqual(names(searchCatalog(expensive, { minPrice: 10 })), ['Telescope']);
  assert.deepEqual(names(searchCatalog(expensive, { minPrice: 10, maxPrice: Infinity })), [
    'Telescope',
  ]);

  // query defaults to '': no name filtering.
  assert.equal(searchCatalog(items, { minPrice: 1 }).length, 4);
  assert.deepEqual(searchCatalog(items, { query: '' }), searchCatalog(items, { query: undefined }));
});

test('undefined option values fall back to the documented defaults', () => {
  const items = fixtures();
  const explicit = searchCatalog(items, {
    query: undefined,
    minPrice: undefined,
    maxPrice: undefined,
  });
  assert.deepEqual(names(explicit), names(items));
});

/* ---------------------------------------------------------- name matching */

test('name matching is case-insensitive in both directions', () => {
  const items = fixtures();
  assert.deepEqual(names(searchCatalog(items, { query: 'GREEN' })), [
    'Green Tea',
    'green coffee',
  ]);
  assert.deepEqual(names(searchCatalog(items, { query: 'green' })), ['Green Tea', 'green coffee']);
  assert.deepEqual(names(searchCatalog(items, { query: 'GrEy' })), ['Earl GREY']);
});

test('matching is a substring test, not a prefix or word test', () =>
  assert.deepEqual(names(searchCatalog(fixtures(), { query: 'at' })), ['Matcha Powder']));

test('query containing spaces matches inside names', () => {
  assert.deepEqual(names(searchCatalog(fixtures(), { query: 'Green ' })), [
    'Green Tea',
    'green coffee',
  ]);
  assert.deepEqual(names(searchCatalog(fixtures(), { query: 'Earl GR' })), ['Earl GREY']);
});

test('whitespace-only query is not treated as empty', () => {
  const items = [
    { id: '1', name: 'Matcha', price: 1 },
    { id: '2', name: 'Two Words', price: 1 },
  ];
  assert.deepEqual(names(searchCatalog(items, { query: ' ' })), ['Two Words']);
  assert.deepEqual(names(searchCatalog(items, { query: '' })), ['Matcha', 'Two Words']);
});

test('a query that matches nothing returns an empty array', () => {
  const result = searchCatalog(fixtures(), { query: 'zzz' });
  assert.ok(Array.isArray(result));
  assert.equal(result.length, 0);
});

test('search only looks at `name` (not id, not numeric price text)', () => {
