    },
    deleteProperty(t, p) {
      seen.delete += 1;
      delete t[p];
      return true;
    },
    defineProperty(t, p, d) {
      seen.define += 1;
      Object.defineProperty(t, p, d);
      return true;
    },
  });
  const watchedItems = rows.map(
    (row) =>
      new Proxy(row, {
        set(t, p, v) {
          seen.set += 1;
          t[p] = v;
          return true;
        },
        deleteProperty(t, p) {
          seen.delete += 1;
          delete t[p];
          return true;
        },
