/**
 * tests/integration.test.mjs — interoperability of the two catalog modules.
 *
 * Composes the published APIs end-to-end: parseCatalog(csvText) -> searchCatalog(items, opts).
 * Nothing is reshaped between the two calls; the assertions are about the combined
 * behaviour (accepted input, case-insensitive names with quoted commas/escaped
 * quotes/embedded CRLF, inclusive bounds, defaults, parser order, non-mutation,
 * empty input, and rejection that stops upstream of search).
 *
 * Node built-in test runner only: no deps, no network. Discovered by `node --test`.
 */

import test from 'node:test';
import assert from 'node:assert/strict';

import { parseCatalog } from '../src/csv.mjs';
import { searchCatalog } from '../src/search.mjs';

/* ------------------------------------------------------------------- fixture */

const CRLF = '\r\n';
const LF = '\n';

/**
 * Small deterministic catalog containing every interop-relevant construct:
 * quoted commas, "" escaped quotes, a CRLF inside a quoted field, mixed-case
 * names, a zero price, an exponent price, and CRLF record separators.
 */
const LINES = [
  'id,name,price',
  '1,Green Tea,3.5',
  '2,"Desk, Oak",120',
  '3,"The ""Big"" One",12',
  '4,earl grey Scone,8.25',
  '5,Matcha Sample,0',
  '6,"Olive, Extra ""Virgin"" Oil\r\n1 Litre",1e3',
];

const CATALOG_CRLF = `${LINES.join(CRLF)}${CRLF}`;
const CATALOG_LF = `${LINES.join(LF)}${LF}`;
const OIL = 'Olive, Extra "Virgin" Oil\r\n1 Litre';

/** Fresh parse per call, so no test can observe another test's objects. */
const catalog = (csv = CATALOG_CRLF) => parseCatalog(csv);

const ids = (rows) => rows.map((row) => row.id);
const names = (rows) => rows.map((row) => row.name);
const prices = (rows) => rows.map((row) => row.price);

/* ------------------------------------------- pipeline that records search calls */

let searchCalls = 0;

/** The order under test: parser output goes straight into search, or nowhere. */
function pipeline(csvText, options) {
  const items = parseCatalog(csvText); // throws before search is reached
  searchCalls += 1;
  return searchCatalog(items, options);
}

/* ------------------------------------------------------- parser output is input */

test('parsed rows are accepted by searchCatalog as-is: same order, same references', () => {
  const items = catalog();
  const result = searchCatalog(items);

  assert.notEqual(result, items, 'search returns a new array');
  assert.equal(result.length, items.length);
  result.forEach((row, index) => {
    assert.equal(row, items[index], `row ${index} is passed through by reference, not copied`);
  });
  assert.deepEqual(ids(result), ['1', '2', '3', '4', '5', '6']);

  // The fields the search contract reads are exactly what the parser emits.
  for (const row of items) {
    assert.deepEqual(Object.keys(row), ['id', 'name', 'price']);
    assert.equal(typeof row.name, 'string');
    assert.equal(typeof row.price, 'number');
    assert.ok(Number.isFinite(row.price) && row.price >= 0, `price ${row.price} is searchable`);
  }
});

test('CRLF and LF catalogs produce equal rows and equal search results', () => {
  const crlf = catalog(CATALOG_CRLF);
  const lf = catalog(CATALOG_LF);
  const filter = { query: 'OIL', minPrice: 100 };

  assert.deepEqual(lf, crlf, 'line-ending style does not change parsed rows');
  assert.deepEqual(names(searchCatalog(lf, filter)), names(searchCatalog(crlf, filter)));
  assert.deepEqual(names(searchCatalog(crlf, filter)), [OIL]);
});

/* ------------------------------------------------------------------- name query */

test('name search over parsed rows is case-insensitive substring matching', () => {
  const items = catalog();

  assert.deepEqual(names(searchCatalog(items, { query: 'GREEN' })), ['Green Tea']);
  assert.deepEqual(names(searchCatalog(items, { query: 'green' })), ['Green Tea']);
  assert.deepEqual(names(searchCatalog(items, { query: 'EARL GREY' })), ['earl grey Scone']);
  assert.deepEqual(names(searchCatalog(items, { query: 'scone' })), ['earl grey Scone']);
