test('quoted commas, escaped quotes and embedded CRLF survive parsing and stay searchable', () => {
  const items = catalog();

  // The comma was quoted in the CSV but is part of the name search must match on.
  assert.deepEqual(names(searchCatalog(items, { query: 'k, O' })), ['Desk, Oak']);
  assert.deepEqual(names(searchCatalog(items, { query: ', OAK' })), ['Desk, Oak']);

  // Literal quotes restored from "" escapes are searchable.
  assert.deepEqual(names(searchCatalog(items, { query: '"big"' })), ['The "Big" One']);
  assert.deepEqual(names(searchCatalog(items, { query: 'EXTRA "virgin"' })), [OIL]);
  assert.deepEqual(names(searchCatalog(items, { query: '"' })), ['The "Big" One', OIL]);

  // The quoted field kept its line break, and the query spans it.
  assert.deepEqual(names(searchCatalog(items, { query: 'oil\r\n1 litre' })), [OIL]);
  assert.deepEqual(names(searchCatalog(items, { query: 'LITRE' })), [OIL]);
});

