  ]);
  assert.deepEqual(names(searchCatalog(items, { minPrice: 120, maxPrice: 120 })), ['Desk, Oak']);
  assert.deepEqual(names(searchCatalog(items, { maxPrice: 8.25 })), [
    'Green Tea',
    'earl grey Scone',
    'Matcha Sample',
  ]);

  // One cent outside either end of a parsed price drops the row.
  assert.deepEqual(names(searchCatalog(items, { minPrice: 120.01 })), [OIL]);
  assert.deepEqual(names(searchCatalog(items, { maxPrice: 119.99, query: 'desk' })), []);
});

