// Independent contract probe (scratch, outside the repo). Not part of the suite.
import { parseCatalog } from '/private/tmp/grapher-cu-20260914/.grapher-worktrees/035972f3-4e96-40c2-b7d7-678f830c268f/verification-report-51302243-dce4-4a9f-af76-7345cc53e2e2/src/csv.mjs';
import searchCatalog, { searchCatalog as named } from '/private/tmp/grapher-cu-20260914/.grapher-worktrees/035972f3-4e96-40c2-b7d7-678f830c268f/verification-report-51302243-dce4-4a9f-af76-7345cc53e2e2/src/search.mjs';

let pass = 0, fail = 0;
const ok = (label, cond) => { if (cond) { pass++; } else { fail++; console.log('PROBE FAIL:', label); } };
const eq = (label, actual, expected) => ok(`${label} -> ${JSON.stringify(actual)} !== ${JSON.stringify(expected)}`, JSON.stringify(actual) === JSON.stringify(expected));
const throws = (label, fn, re) => { try { const r = fn(); fail++; console.log('PROBE FAIL (no throw):', label, JSON.stringify(r)); } catch (e) { if (re && !re.test(e.message)) { fail++; console.log('PROBE FAIL (wrong msg):', label, e.message); } else pass++; } };

/* ---- csv ---- */
eq('shape', parseCatalog('id,name,price\n1,A,2'), [{ id: '1', name: 'A', price: 2 }]);
ok('keys order', Object.keys(parseCatalog('id,name,price\n1,A,2')[0]).join() === 'id,name,price');
eq('quoted header', parseCatalog('"id","name","price"\n1,A,2'), [{ id: '1', name: 'A', price: 2 }]);
eq('esc quote tail', parseCatalog('id,name,price\n1,"a""",2'), [{ id: '1', name: 'a"', price: 2 }]);
eq('stray quote unquoted', parseCatalog('id,name,price\n1,a",2'), [{ id: '1', name: 'a"', price: 2 }]);
eq('newline before close quote', parseCatalog('id,name,price\n1,"a\n",2'), [{ id: '1', name: 'a\n', price: 2 }]);
eq('CR inside quotes kept', parseCatalog('id,name,price\r\n1,"a\rb",2\r\n'), [{ id: '1', name: 'a\rb', price: 2 }]);
eq('no trailing newline', parseCatalog('id,name,price\n1,A,2'), [{ id: '1', name: 'A', price: 2 }]);
eq('trailing blank lines', parseCatalog('id,name,price\n1,A,2\n\n\n'), [{ id: '1', name: 'A', price: 2 }]);
eq('empty', parseCatalog(''), []);
eq('blank', parseCatalog('\n  \n\t\n'), []);
eq('null', parseCatalog(null), []);
eq('undefined', parseCatalog(), []);
eq('BOM only header', parseCatalog('\uFEFFid,name,price'), []);
eq('zero/-0', parseCatalog('id,name,price\n1,A,-0\n2,B,0').map((r) => r.price), [0, 0]);
ok('-0 not negative zero', Object.is(parseCatalog('id,name,price\n1,A,-0')[0].price, 0));
eq('exponent', parseCatalog('id,name,price\n1,A,1.5e2')[0].price, 150);
eq('id stays string', typeof parseCatalog('id,name,price\n007,A,2')[0].id, 'string');
throws('bad header', () => parseCatalog('a,b,c\n1,2,3'), /header/i);
throws('header wrong order', () => parseCatalog('name,id,price\nA,1,2'), /header/i);
throws('too few cols', () => parseCatalog('id,name,price\n1,A'), /malformed row on line 2/i);
throws('trailing comma row', () => parseCatalog('id,name,price\n1,A,2,\n'), /malformed row on line 2/i);
throws('empty id', () => parseCatalog('id,name,price\n ,A,2'), /empty id/i);
throws('negative', () => parseCatalog('id,name,price\n1,A,-2'), /negative price/i);
throws('Infinity', () => parseCatalog('id,name,price\n1,A,Infinity'), /price/i);
throws('1e400', () => parseCatalog('id,name,price\n1,A,1e400'), /price/i);
throws('underscore numeric', () => parseCatalog('id,name,price\n1,A,1_000'), /invalid price/i);
throws('unterminated', () => parseCatalog('id,name,price\n1,"a,2'), /unterminated quoted field/i);
throws('unterminated in header', () => parseCatalog('id,"name,price\n'), /unterminated quoted field/i);
throws('non-string input', () => parseCatalog(123), TypeError);

/* ---- search ---- */
ok('default === named export', default === named || typeof default === 'function');
const items = parseCatalog('id,name,price\r\n1,Green Tea,3.5\r\n2,"Desk, Oak",120\r\n3,earl grey,8.25\r\n4,Matcha,0\r\n');
const snapshot = JSON.stringify(items);
eq('defaults return all', searchCatalog(items).map((r) => r.id), ['1', '2', '3', '4']);
eq('case-insensitive substring', searchCatalog(items, { query: 'DESK, oa' }).map((r) => r.id), ['2']);
eq('inclusive bounds', searchCatalog(items, { minPrice: 3.5, maxPrice: 8.25 }).map((r) => r.id), ['1', '3']);
eq('query+bounds AND', searchCatalog(items, { query: 'e', minPrice: 4 }).map((r) => r.id), ['2', '3']);
ok('no mutation', JSON.stringify(items) === snapshot);
ok('new array', searchCatalog(items) !== items);
throws('min>max', () => searchCatalog(items, { minPrice: 5, maxPrice: 1 }), RangeError);
throws('negative bound', () => searchCatalog(items, { minPrice: -1 }), RangeError);
throws('string bound', () => searchCatalog(items, { maxPrice: '5' }), TypeError);
throws('non-string query', () => searchCatalog(items, { query: 5 }), TypeError);
throws('non-array', () => searchCatalog('nope'), TypeError);

console.log(`probe: ${pass} ok, ${fail} failed`);
process.exit(fail ? 1 : 0);

